        expect\(m.progressPicsLoaded\).toBe\(false\);
    }\);

    it\('loads photos for each date', async \(\) => {
        const Supa = await import\('../store/supabase.js'\);
        const m = createMixin\({
            history: [
                { date: '2025-01-01', weight: 80 },
